INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('pushpak-ac-service','AC service platform','Pushpak Refrigeration Centre','AC service company · New Delhi','ERP / CRM','Home services','Customers book AC service, repair or installation, approve the technician''s estimate in-app, pay and keep a service history per AC. The owner dispatches jobs, tracks technicians, parts, invoices with GST, AMC contracts, payroll and per-job / per-technician profit from a large admin panel.','Main workflow: Customer books a visit with complaint and slot → Admin assigns a technician in Jobs & Dispatch → Technician travels, verifies visit OTP, diagnoses and sends an estimate → Customer approves; technician completes work and collects payment → Invoice issued, AC service history and profit reports update','["Customer Home: Book service CTA, my ACs, active booking timeline, ''Buying a new AC? Find the right size''…", "Book service: Pick AC, complaint (No Cooling, Water Leakage, Noise, Error Code...), date and slot (9-11…", "Bookings / Job page: 12-step job timeline, technician details, visit OTP, quotation to approve, invoice,…", "Technician Jobs: Assigned jobs list and job detail with pre-work checklist, diagnosis, quote builder, job…", "Technician Calculators / Stock: 25 calculators (copper pipe weight & price, tonnage, GST, energy), van stock of parts", "Admin Dashboard + Jobs & Dispatch: KPIs, job board by status, unassigned requests, technician availability"]'::jsonb,'["Next.js 16", "localStorage demo store", "Supabase planned"]'::jsonb,'coming_soon',10) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('airawat-store','Furniture e-commerce store','Airawat Handicraft','Handcrafted furniture brand · Pune','E-commerce','Furniture & handicrafts','An online furniture store for the client where shoppers browse sofas, beds, dining and decor by room, pick finish/size variants, check pincode delivery and check out with UPI, card or COD. Staff manage products, categories, orders (with Shiprocket shipping), coupons, sign-up offers and reviews from an admin panel.','Main workflow: Shopper picks a room (Living / Bedroom / Dining) and a product → Chooses finish and size, checks pincode delivery → Adds to cart, applies coupon, pays by UPI/card/COD → Admin sees paid order, clicks Ship to create Shiprocket shipment → Customer tracks order status until delivered','["Home: Hero carousel, shop-by-room cards, best sellers, sign-up offer banner, sticky WhatsApp…", "Category / Listing: Product grid with price vs MRP, rating, ''ships fast'' and deal badges; filters by…", "Product page: Gallery, buy box with finish swatches and size options, price/MRP/discount, dimensions,…", "Cart & Checkout: Line items, bundle and coupon discounts, summary; address form; payment choice UPI / Card…", "Order tracking: Order code, status, lines, shipping tracking; account orders and wishlist", "Admin Dashboard: Sales and order KPIs, recent orders"]'::jsonb,'["Next.js 15", "Supabase", "Postgres", "auth", "Shiprocket API", "Netlify"]'::jsonb,'coming_soon',20) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('airawat-showroom','Showroom stock & quotation app','Airawat Handicraft','Handcrafted furniture brand · Pune','ERP / CRM','Furniture & handicrafts','A phone-first staff app for the client''s showroom, warehouse and branches: find any product by name, SKU, size or barcode scan, see exactly which rack/location holds stock, and reserve, transfer or dispatch pieces with a full stock ledger. Sales staff build customer shortlists, turn them into quotations/orders, print Code 128/QR labels and share a public product or catalogue page on WhatsApp.','Main workflow: Customer points at an item; salesperson scans its label → App shows availability per location and rack → Salesperson adds it to the customer''s shortlist and creates a quotation → Quotation is confirmed as an order (stock reserved all-or-nothing) → Storekeeper dispatches from warehouse; ledger records the movement','["Find: Search box (name, SKU, barcode, category, material, finish, size like 120x60) with result…", "Scan: Camera barcode/QR scanner (or USB/Bluetooth scanner) with action picker", "Product / Piece detail: Photos, specs, dimensions, price, available/reserved/physical stock, stock by location…", "Shortlists: Customer shortlists with items, compare view, linked quotations", "Stock: Incoming (purchase/production), reservations, stock ledger, cycle counts", "More: Label batch builder (A4 sheet / thermal PDF / ZPL), enquiries from staff and public QR,…"]'::jsonb,'["Node/Express API", "vanilla JS staff app", "no build", "Postgres", "Supabase", "Supabase Storage"]'::jsonb,'coming_soon',21) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('xeal-whatsapp-crm','WhatsApp AI assistant + lead CRM','Xeal Education','Study-abroad consultancy','AI applications','Education consultancy','A WhatsApp bot answers student enquiries about studying MBBS abroad (Russia, Georgia, Kyrgyzstan, Philippines and Indian private colleges), mirrors the student''s tone, scores and stages each lead, sends PDF brochures and hands over to a human counsellor when needed. Staff manage leads, conversations, the knowledge base, follow-ups and bulk broadcasts from a Next.js dashboard.','Main workflow: Student messages the consultancy WhatsApp number → Bot asks discovery questions (country, NEET marks, 12th %, budget) and scores the lead → Bot sends the right country brochure PDF and answers FAQs from the knowledge base only → Hot or confused leads are escalated; counsellor takes over from the dashboard → Automatic follow-ups re-engage idle leads until converted or closed','["Dashboard: KPIs (new leads, hot leads, escalations, conversions), recent leads table with stage…", "Leads: Table of leads with name, WhatsApp number, country, course, NEET status, score,…", "Conversations: WhatsApp-style transcript per lead (student/bot/staff), buttons and PDFs sent", "Knowledge Base: Countries (universities, fees, duration, eligibility, NMC/WHO recognition), courses,…", "Documents: Brochure PDFs per country", "Analytics: Leads by stage, country, temperature; conversion funnel"]'::jsonb,'["Node/Express", "Baileys", "WhatsApp Web", "Next.js dashboard on Vercel", "npm workspaces monorepo"]'::jsonb,'coming_soon',30) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('aquaphil-water-care','Water purifier store + service booking','Aquaphil Water Care','Water purifier company · Bengaluru','E-commerce','Home services','Customers buy RO purifiers, filters and spares, and book installation, repair, filter change or AMC visits with live technician tracking and in-app chat. Technicians accept jobs and record work and payments, while the admin console manages orders, service jobs, technicians, products and stock, and offers.','Main workflow: Customer logs in with mobile OTP → Buys a purifier or books a service with a time slot → Technician is auto-assigned and customer tracks them live → Technician completes job, records TDS and parts, collects payment → Customer rates the technician and gets a GST invoice','["Home: Location, search, banner, quick actions, shop by category, offers, services, popular…", "Shop: Domestic RO, Commercial RO, Spare Parts, Filters, Accessories; product cards with…", "Cart & Checkout: Items, address, coupon, wallet, UPI / Card / COD", "Service: Service catalogue (Installation, Repair, AMC, Filter Change, Water Test, Uninstall),…", "Live tracking: Map with technician ETA and 6-step tracker (Requested, Assigned, On the Way, In Progress,…", "Chat / Orders / Profile: Support, technician and billing threads; my orders and service history; My AMC plan,…"]'::jsonb,'["Next.js 16", "in-memory sample data", "Supabase planned"]'::jsonb,'none',40) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('water-delivery','Water-can delivery marketplace',NULL,'On-demand delivery platform','Custom software','Delivery','Households order 20L water cans and bottled water from nearby vendors, subscribe to monthly plans, pay by UPI/COD/wallet and track the delivery live with OTP proof and can-return tracking. Vendors manage pricing, service areas, drivers, vehicles and settlements, while the platform admin runs dispatch, pricing controls, vendor monetization, coupons, ads and cities.','Main workflow: Customer orders 2 x 20L cans for now → Platform searches nearby vendors'' drivers and offers the job → Driver accepts, picks up and navigates to the customer → Driver exchanges empty cans and verifies the customer''s OTP → Payment confirmed; vendor settlement and commission recorded','["Customer Home: Address, nearby vendor products (20L can, 10L can, Bisleri jar, bottle packs), ad slot,…", "Order & Tracking: Cart with deposit for cans, slot picker, payment method; live map tracker (Order…", "Plans: Monthly subscription plans (e.g. 30 cans/month) with entitlement left", "Driver app - Deliveries: Incoming request with distance and countdown, active delivery with navigation, can…", "Vendor panel: Dashboard, Orders, Products & Pricing, Service Areas (radius/PIN/locality/polygon),…", "Super Admin: Orders & Dispatch, Vendors (KYC), Drivers, Customers, Pricing Controls, Vendor…"]'::jsonb,'["Next.js 16", "Supabase-ready types", "i18n"]'::jsonb,'none',50) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('hirenova-portal','Recruitment job portal','Hirenova Workforce','Recruitment agency · West Bengal','Websites','Recruitment','Public website and portal connecting employers in South-East Europe (Serbia, North Macedonia, Bosnia, Albania, Montenegro, Croatia, Bulgaria) with workers from India, Nepal, Bangladesh, Sri Lanka, Indonesia and the Philippines. Employers post vacancies and browse verified workers; job seekers search jobs and track applications; admins approve employers and vacancies.','Main workflow: Employer registers and is verified by admin → Employer posts a vacancy which admin approves → Job seeker registers, searches jobs and applies → Employer shortlists, requests interview; documents release in stages → Selected worker moves to documentation and hired','["Home: Hero, country cards with flag stripes, industries, how it works, featured jobs", "Jobs: Job search with filters (country, industry, salary) and job detail with salary, hours,…", "Employer Dashboard: ''Good morning'' greeting, vacancy list, recommended candidates, applications pipeline", "Post Vacancy: Multi-section form: role, workers needed, salary, hours, overtime, contract, benefits,…", "Find Workers / Candidate Profile: Anonymised candidate cards (ID, nationality, profession, experience, languages,…", "Track your applications: Job seeker timeline: Applied, Under review, Shortlisted, Interview, Selected,…"]'::jsonb,'["Next.js 16", "plain CSS design tokens", "in-memory data", "no backend yet"]'::jsonb,'none',60) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('hirenova-lead-engine','Recruitment CRM + lead engine','Hirenova Workforce','Recruitment agency · West Bengal','ERP / CRM','Recruitment','Internal back-office for Hirenova: create overseas vacancies, generate ad copy and reel scripts with AI, run Facebook/Instagram lead campaigns, and capture, AI-qualify and move worker leads through a Kanban pipeline to hire. It also keeps candidate and employer databases, WhatsApp messaging and analytics with role-based access.','Main workflow: Recruiter creates a vacancy from an employer order and gets it approved → Marketing generates ad copy/reel script with AI and launches a Meta lead campaign → Leads flow in from Lead Ads/website/WhatsApp and are AI-qualified against the vacancy → Recruiter moves qualified leads through documents and interview on the Kanban board → Selected leads become candidates and are marked Hired; analytics show cost per hire','["Dashboard: Stat cards (leads, qualified, interviews, hires), leads-over-time chart, pipeline flow,…", "Vacancies: Table of jobs with reference, country, city, positions, salary range EUR, status", "AI Content Studio: Generate Facebook posts, Instagram captions, reel scripts, WhatsApp messages for a…", "Campaigns / Meta Marketing: Campaigns by platform and objective, spend, leads, CPL", "Leads: Lead table with source, profession, vacancy, stage, qualification status", "Lead Pipeline: Kanban columns New, Contacted, Qualified, Documents Pending, Interview, Selected, Hired,…"]'::jsonb,'["Next.js 15 App Router", "shadcn-style UI", "Prisma", "PostgreSQL", "23 tables", "RBAC"]'::jsonb,'none',61) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('textile-pickup','Doorstep textile recycling pickup app','JIJA Textile Recovery Facility','Textile recycling facility · Panvel','Mobile apps','Recycling','Residents of Panvel book free doorstep pickups of old clothes and footwear, find drop-point bins and centres, and follow each kilo through Collect, Sort, Reuse, Recycle. The app shows personal impact (kg diverted, CO2 saved, badges) and tracks each pickup from scheduling to sorting.','Main workflow: Open app and tap Schedule pickup → Choose address, day, slot, item type and bags → Partner is assigned and collects the bags → Bags are weighed and sorted at the Panvel facility → User sees kg and CO2 added to their impact and badges','["Home: Greeting, notification bell, ''Got clothes to give up?'' hero, Panvel loop ring (2,840 kg…", "Pickup: Address picker, next 7 days, time slot (morning/afternoon/evening),…", "Track pickup: Timeline Scheduled > Partner assigned > Picked up > Weighed at facility > Sorted, partner…", "Points: Schematic map with pins, list filtered by Bins/Centers/Open now, hours", "Impact: Total kg, CO2 saved, garment equivalents, ''Where it went'' breakdown, badges, history", "Profile: Stats, month streak, saved addresses, notifications, help and FAQs"]'::jsonb,'["Next.js 16", "in-memory demo data", "Supabase planned"]'::jsonb,'none',70) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('ridewallah','Ride & parcel booking app','Ridewallah','Ride-hailing start-up','Mobile apps','Mobility','the client is an Uber-style booking platform for Bike, Auto, E-rick, Mini, Sedan and SUV rides plus parcel delivery, with a customer app, a rider (driver) app and an admin panel in one Next.js project. Customers book, track, pay and rate; riders go online, accept trips and track earnings; admins manage pricing, KYC, coupons and live rides.','Main workflow: Customer enters pickup and drop, compares vehicle fares and books → Nearby rider receives the request and accepts → Customer tracks the rider arriving and shares the OTP to start → Trip completes; customer pays by UPI/cash and rates → Admin monitors live rides and adjusts pricing/surge','["Customer Home: Map, pickup/drop pickers with saved places (Home, Work, recents), Ride vs Parcel toggle,…", "Ride tracking: Status steps Searching → Assigned → Arriving → Arrived → Started → Completed, driver card…", "Rides / Offers / Support / Profile: Ride history with fares, coupon list, support tickets, profile and wallet", "Rider Home: Online toggle, incoming request card with fare and pickup distance, hotspots", "Rider Earnings / Incentives: Daily/weekly earnings, wallet and instant payout, incentive targets, performance and…", "Admin Dashboard / Live Rides: KPIs (rides, revenue, online drivers), live ride table, map"]'::jsonb,'["Next.js 16", "Supabase", "catalog", "auth", "with in-memory demo data"]'::jsonb,'none',80) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('swanidhi-admissions','Admissions CRM app','Swanidhi Group of Institutions','Group of colleges','Mobile apps','Education','An Android app wrapping the Swanidhi admissions CRM: counsellors capture and follow up on admission enquiries, track students, documents and fee collection, and manage staff attendance, payroll and targets. Students see admission status and fees; referral associates see their wallet and referred students. Current APK runs an offline demo CRM on dummy data.','Main workflow: Enquiry arrives (website, walk-in, WhatsApp, associate referral, Excel import) and is assigned to a counsellor → Counsellor calls/WhatsApps from the app and logs status + next follow-up → Interested student counselled; documents received by backend team → Admission converted; fee collected and receipt generated; associate commission credited → Student tracks admission and fees in the student portal','["Splash / Onboarding: Navy splash with logo; 3 slides: ''Every Lead in one place'', ''Students & Fees always up to…", "Dashboard: Today''s follow-ups, new leads, conversions, fees collected, team performance", "Leads / My Leads: Lead list with course, city, source, assigned counsellor, status, follow-up date", "Students / Documents: Admitted students by course and session; document checklist", "Fees / Finance / Courses & Fees: Fee received entries (UPI, cash, NEFT, card, cheque), course fee structure (e.g. B.Sc…", "HRMS / Attendance / Targets / Tasks / Team: Staff punch-in, payroll, monthly admission targets, tasks"]'::jsonb,'["Native Android", "Java", "WebView shell with JS bridge", "real CRM", "separate repo", "on Supabase"]'::jsonb,'none',90) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('reinvent-workshop','Workshop website + registrations','Reinvent Yourself','Life-coaching workshop','Websites','Coaching','A landing page selling a live online workshop, ''Life Coach Launchpad'', that teaches women how to become part-time life coaches without quitting their job (₹99, struck-through ₹999). Visitors register via a modal form and an admin portal lists registrations with stats and CSV export.','Main workflow: Visitor lands on the page and reads the workshop pitch → Clicks ''Reserve My Seat — ₹99'' and fills the form → Sees confirmation (updates via WhatsApp and email) → Admin signs in, reviews registrations and exports CSV','["Landing – hero: ''Live workshop • Exclusively for women'', headline ''Your experience. Your purpose. Serve…", "The Workshop / What You''ll Learn: Audience cards (returning after a break, looking for your own path, ready to move…", "What we offer / Your Mentor: Offer tiles: Personal 1:1, Programs (live events), Products (courses), Membership,…", "Registration modal: Full name, Email, WhatsApp number, Profession, City; success ''You''re registered!''", "Admin – Registrations: Password sign-in, stats (Total, Today, Last 7 days, Top city), table (Name, Email,…"]'::jsonb,'["Static HTML/CSS/JS", "Netlify Functions", "Netlify Blobs", "local Python server for dev"]'::jsonb,'none',100) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('manas-library','Study library management system','Manas Library','Study-library chain · Patna','Management systems','Education','A multi-branch management system for a paid self-study library chain: staff admit students on monthly/quarterly/yearly plans, allocate numbered seats in time batches, track attendance (manual or biometric) and raise invoices with fee reminders. Each branch sees only its own data while the super admin sees all branches and reports.','Main workflow: Walk-in student is admitted at a branch and chooses a plan → Staff allocates a free seat in the chosen time batch → Invoice generated; payment recorded via cash/UPI → Daily attendance via biometric device or manual check-in → Fee reminders go out before expiry; student renews or seat is released','["Dashboard: Greeting banner, active students, seats occupied/available, today''s attendance, fees…", "Students: Student list with code, phone, plan, seat, expiry, status; student profile with history", "Admissions: Admission wizard: student details -> plan (Monthly Rs 1,200 / Quarterly Rs 3,300 /…", "Seats: Seat map grid by floor/section; colour by status (available, occupied, reserved,…", "Batches: Time batches (Morning 06:00-10:00, Afternoon 12:00-16:00, Evening 17:00-21:00) with…", "Attendance: Today''s check-ins (manual/biometric), history"]'::jsonb,'["Next.js 14 admin console", "Express", "TypeScript API", "Supabase Postgres", "RLS", "shared TS package"]'::jsonb,'none',110) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('careeroptics-web','College discovery site + CMS + CRM','CareerOptics Education','Education counselling firm · Bihar','Websites','Education','A Collegedunia-style portal where students browse colleges, courses, exams and scholarships and submit enquiries (Apply Now, counselling, College Finder wizard) that land as leads for counsellors. Behind it sits an admin CMS for content and a full staff CRM (leads, associates/partners, fees, HRMS, targets, finance) plus a student portal.','Main workflow: Student lands on the site and browses colleges or runs the College Finder → Submits Apply Now / counselling form -> lead created and staff alerted → Telecaller calls, updates status, schedules campus visit → Backend team processes admission and documents; finance records fee → Admitted student gets portal access; associate earns commission if referred','["Home: Hero with course chips (B.Tech, MBA, MBBS, B.Sc Nursing, BCA...), search, featured…", "Colleges / College detail: Filterable college list (city, type, course, fees); detail page with NAAC/NIRF, packages,…", "College Finder: Multi-step wizard: level, stream, budget, city preference -> matched colleges", "Courses / Exams / Scholarships: Course pages, entrance exam pages, scholarship listings, guides after 10th/12th/graduation", "CRM > Leads: Lead table with source, course, assigned counsellor, status, follow-up; lead detail…", "CRM > Associates: Referral partner list with commission, referred students, wallet"]'::jsonb,'["Next.js 15 App Router", "shadcn/ui", "Supabase", "Postgres/RLS/Storage", "Resend", "Upstash"]'::jsonb,'none',120) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('careeroptics-erp','Computer institute franchise ERP','Career Optics Computer Academy','Computer training institute chain','ERP / CRM','Education','A head-office ERP for a computer-training franchise (ADCA, DCA, Tally, etc.) that runs reception enquiries, student admissions, batches, fee collection, attendance, exams, admit cards, marksheets and certificates across many branches. Head office also manages franchise branches with wallets, recharges, centre charges and notice boards, and students get their own portal.','Main workflow: Receptionist logs a walk-in enquiry for ADCA → Enquiry converted to admission; enrollment no. and ID card generated → Student assigned to batch; fee group allocated and first instalment collected with receipt → Attendance marked daily (incl. QR attendance); online/offline exam conducted → Results published; marksheet and certificate printed after approval','["Home: KPI cards: today''s enquiries, admissions, fee collected, dues, attendance; quick actions", "Reception > Visitors & Enquiries: Walk-in visitor and enquiry list with course interest, follow-up date, status", "Student Management > Admission Form / View Students: Multi-section admission form (personal, Aadhaar/APAAR, address, course, batch) and…", "Fee Management > Fee Collection / Due Fee Collection: Fee types (Tuition, Admission, Exam, Lab...), fee groups, student ledger, dues list", "Course Management: Courses (ADCA, DCA, Tally Prime, ADCA-AI), batches, batch timings, syllabus, subjects", "Exam & Marks: Exam centres, schedule, admit cards, results & marksheets, online exam/question bank,…"]'::jsonb,'["React", "Vite", "Radix/shadcn", "organization/", "Express 5", "Prisma"]'::jsonb,'none',121) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('clatians-lms','Learning management system','CLATians','Law entrance coaching · Patna','Management systems','Education','A learning platform for a CLAT coaching institute: students get a mobile-style app with courses, live classes, video lectures, notes, mock tests, doubts and an AI tutor, while teachers run classes, tests and doubt-solving. Admins manage admissions/leads, courses, batches, faculty, fees and payments, announcements and an audit log; there is also a parent portal and an Android (Capacitor) wrapper.','Main workflow: Enquiry captured as lead; counsellor books demo, lead marked enrolled → Student pays via UPI and is enrolled in course/batch → Student watches lectures, reads notes and attends live classes → Takes full the client mock test, reviews explanations, sees leaderboard rank → Raises doubt; teacher or AI tutor answers; parent views progress','["Home: Selected course hero, quick tiles: Video lectures, Study Notes, Practice Questions,…", "Courses: Course catalog (CLAT Coaching, CLAT + AILET Combined, CUET-UG Law, Online CLAT Course,…", "Study: Subject > module > chapter > lesson tree (Legal Reasoning: Torts, Contract, Criminal Law;…", "Tests: Full mock tests (all sections), timer, passage-based questions, result with…", "Doubts: Doubt threads per subject with teacher answers; AI tutor chat", "Admin > Dashboard / Admissions: Students, revenue, leads pipeline (new, contacted, demo, enrolled), global student search"]'::jsonb,'["Next.js 16 App Router", "Supabase Postgres via pg", "Google Gemini", "AI tutor", "Vercel Blob", "Capacitor Android wrapper"]'::jsonb,'none',130) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('clatians-whatsapp-crm','WhatsApp AI assistant + lead CRM','CLATians','Law entrance coaching · Patna','AI applications','Education','A WhatsApp bot that answers the client admission enquiries automatically (menus, buttons, AI answers grounded in a knowledge base), sends batch brochures and fee PDFs, scores leads hot/warm/cold and escalates to a human counsellor. Staff use a dashboard to see leads, chat transcripts, follow-ups and to send bulk messages.','Main workflow: Student messages the institute WhatsApp number → Bot replies with menu buttons (target exam, programme, budget) and answers questions from the knowledge base → Bot sends the right batch brochure / fee PDF and scores the lead → Hot or confused leads are escalated; counsellor takes over in the dashboard → Scheduled follow-ups and bulk messages nurture until enrolled (closed_won)','["Dashboard: Lead counts by temperature and stage, today''s chats, escalations needing a human, AI…", "Leads: Lead table: name, WhatsApp number, target exam, programme, budget, stage, score,…", "Lead detail: Profile, WhatsApp transcript, documents sent, stage history", "Conversations: WhatsApp-style chat inbox with bot and human messages", "Knowledge Base / Catalog / Documents: Courses, batches, FAQs, admission steps; uploaded brochures and fee structures", "Scheduled Follow-ups / Bulk Message: Automatic reminder queue; broadcast composer to filtered leads"]'::jsonb,'["Node/Express", "Baileys", "WhatsApp Web", "Gemini with Groq fallback", "Next.js dashboard", "Supabase Postgres"]'::jsonb,'none',131) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('skyhigh-event-booking','School event slot booking','Sky High Educational Services','Education services firm · Jamshedpur','Management systems','Education','Schools pick a state, city, school, event date and time slot for Sky High''s career-guidance summits, edit a pre-written message and confirm; the slot turns red and shows the school''s name, and emails go to the Sky High office, the director (CC) and the school. Admins manage states, cities, schools, events, dates, slots, photos/logos, bookings and email templates without code.','Main workflow: School rep opens the shared link; Jharkhand/Jamshedpur pre-selected with event photos → Selects school and an available date → Picks a green slot, enters email, edits the predefined message → Confirms; slot turns red with school name and reference code shown → Office + director (CC) + school receive emails; admin manages bookings in portal','["Book: Stepper: state (default Jharkhand), city (default Jamshedpur), school dropdown, event…", "Booking confirmation: Reference code (e.g. JSR-...), event, date, slot, school, venue; email sent notice", "Admin > Dashboard: Bookings today/this week, slots filled per event, pending school reviews, email delivery…", "Admin > Bookings: Filterable bookings table (event, city, date, status) and booking detail with status…", "Admin > Events: Events per city with dates, slot schedule, media (logo, banner, gallery)", "Admin > Schools / Cities / States: Master data lists with active toggle; schools pending review from ''not listed'' submissions"]'::jsonb,'["Next.js 16 App Router", "Supabase", "Postgres", "Auth", "Storage", "RLS"]'::jsonb,'none',140) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('skyai-whatsapp-crm','WhatsApp AI assistant + lead CRM','Sky High Career Consultancy','Study-abroad consultancy · Srinagar','AI applications','Education consultancy','An AI WhatsApp counsellor for an MBBS-abroad consultancy that chats with NEET students in Hinglish, mirrors their tone, checks eligibility, sends country brochures and fee sheets, scores leads and escalates to human counsellors. A dashboard shows leads, conversations, knowledge base (countries, universities, fees), follow-ups, bulk messaging and analytics.','Main workflow: NEET student messages on WhatsApp in Hinglish → AI counsellor replies in matching tone, asks NEET score, 12th %, budget → Recommends country and sends brochure + fee sheet PDF → Lead scored; hot leads escalated to human counsellor in dashboard → Follow-ups until documents collected and admission converted','["Dashboard: Hot/Warm/Cold counts, new inquiries today, escalations, converted this month, AI quota", "Leads: Table: name, WhatsApp, country (Russia, Georgia, Kyrgyzstan, Philippines...), course…", "Lead detail: Profile (NEET marks, 12th %), tone profile (hinglish, aap), documents shared, chat…", "Conversations: WhatsApp-style inbox of bot/human chats", "Knowledge Base: Countries with universities, total fee range, duration, eligibility, recognition (NMC),…", "Documents: Country brochures and fee sheets (PDF) sent by the bot"]'::jsonb,'["Node/Express", "Baileys", "Gemini", "Groq fallback", "on Railway", "Next.js dashboard on Vercel"]'::jsonb,'none',141) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('adenium-store','Plants & seeds e-commerce store','Adenium','Plant nursery brand','E-commerce','Gardening','A D2C online store selling adenium (desert rose), cactus and succulent seeds and live plants across India, where each product page doubles as a growing guide with germination time, temperature, light and care notes. Admins manage orders, products and variants, inventory, bulk CSV import, coupons, reviews, customers and reports, with Razorpay prepaid checkout.','Main workflow: Customer browses Seeds > the client Seeds and reads the growing data → Picks pack size or pot size and adds to cart → Pays via Razorpay; webhook confirms the order → Admin packs, enters courier AWB and marks shipped → Customer tracks the order and leaves a review','["Home: Hero, Seeds and Plants entry points, featured products, growing guides, newsletter", "Seeds / Plants category pages: Product grid filterable by category (the client Seeds, Cactus Seeds, Succulent Seeds,…", "Product page: Botanical name, variant picker (pack size or pot size/height), price vs compare-at, low…", "Cart & Checkout: Cart, address, coupon, Razorpay (UPI/cards/netbanking)", "Account / Track order: Orders with status and AWB, addresses, wishlist, reviews, profile; public order tracker", "Growing guides: Guide articles linked to products"]'::jsonb,'["Next.js 16 App Router", "PostgreSQL", "Prisma 6", "DB sessions with bcrypt", "Razorpay", "Nodemailer"]'::jsonb,'none',150) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('drivonex-store','Car accessories store','Drivonex','Car accessories brand','E-commerce','Automotive','A mobile-first D2C store for the client car electronics: 4K dash cams, wireless CarPlay/Android AI boxes, reverse cameras, speakers and lighting, with a vehicle-compatibility checker to prevent wrong-fitment returns. Browse, cart and cash-on-delivery checkout work; Razorpay, Shiprocket and the admin panel are not built yet.','Main workflow: Customer lands on home and opens CarPlay AI Boxes → Enters car make/model/year to check fitment on the product page → Picks a variant and adds to cart, applies WELCOME10 → Checks out: address with pincode autofill, delivery, COD → Gets thank-you page and tracks order in account','["Home: Hero, category tiles, featured products, offers, WhatsApp button", "Categories / Category listing: Car Electronics → Dash Cameras (single/dual channel), CarPlay & Android AI Boxes, Reverse…", "Product page: Gallery, price/MRP/discount, variants (bundle or memory), specs, what''s in the box,…", "Search: Search results", "Cart: Line items, quantities, coupon (WELCOME10), totals", "Checkout: 3-step accordion Address → Delivery → Payment, pincode autofill, COD or prepaid"]'::jsonb,'["Next.js 16 App Router", "Supabase", "Postgres", "Auth", "Storage", "not wired"]'::jsonb,'none',160) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('weddingmall','Wedding vendor marketplace','WeddingMall','Wedding marketplace','Custom software','Weddings','Couples search wedding vendors (venues, photographers, makeup artists, caterers, decorators, mehendi, planners) by category and city, shortlist them, and send enquiries or ''Book now'' requests. Vendors manage their listing, packages, portfolio, availability and enquiry inbox, while admins verify vendors, moderate listings and reviews, and manage cities, categories and paid plans.','Main workflow: Couple searches ''Photographers in Mumbai'' → Opens a vendor profile and compares packages → Taps Book now, enters name, mobile, date, guests → Vendor sees the enquiry in the dashboard, replies and sends a quote → Enquiry moves to booked; couple leaves a review','["Home: Maroon hero with search (category + city), city selector, category circles/carousel,…", "Browse vendors: Vendor cards with cover photo, rating, starting price, city; filters and sort", "Vendor profile: Portfolio gallery, services, packages with price ranges, FAQs, policies, reviews,…", "Customer account: Wedding profile (date, city, budget), shortlist, enquiries with message threads, reviews,…", "Vendor dashboard: Enquiry inbox with stages, listing editor, packages, portfolio, availability calendar,…", "List your business: Multi-step listing wizard and verification submission"]'::jsonb,'["Next.js App Router", "Supabase", "Postgres", "RLS", "storage", "realtime"]'::jsonb,'none',170) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('aqoss-hotel-saas','Hotel booking engine + CRM (SaaS)','AQOSS','Hospitality software company','SaaS','Hospitality','the client lets a hotel group run many hotel websites from one CRM: each hotel gets its own branded booking website on a subdomain, with live room inventory, rates, offers and online payment. Staff manage bookings, rooms and inventory, payments and payouts, offers, reviews and analytics, while guests book and see their stays in a customer dashboard.','Main workflow: Admin creates a hotel and its free website from the CRM → Sets room types, rates and inventory per date → Guest books on the hotel''s own website and pays online → Booking manager checks the guest in and out → Finance records payout to the property; analytics update','["Hotel website: Hero, rooms list, room detail, reviews, location, property rules, date + guests search", "Booking flow: Dates, room type, pax pricing, guest details, payment, confirmation with reference", "CRM Home: KPIs, charts, recent bookings, quick actions", "Hotels & Properties: List of hotels with status and website link; per-hotel panel (details, images, rooms,…", "Bookings: Bookings table with guest, dates, nights, room, amount, status, payment status", "Rooms & Inventory / Pricing: Room types, per-date inventory grid with 1 pax / 2 pax / extra person / extra child…"]'::jsonb,'["Next.js 14 App Router", "Supabase", "auth", "storage", "Recharts", "Razorpay adapter"]'::jsonb,'none',180) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('newvisa-crm','Visa consultancy CRM + travel booking','NewVisa Global Odyssey','Immigration consultancy','ERP / CRM','Immigration','Public website where people check visa eligibility for Canada, Australia, UK, USA, Germany, New Zealand, Dubai and Schengen, book a consultation and become leads auto-assigned to counsellors. Customers then upload documents, track their application and book flights and hotels, while staff manage leads, applications, documents, payments, markups and CMS from a role-based admin panel.','Main workflow: Visitor completes the eligibility check or consultation form → Lead is scored and auto-assigned to a counsellor → Counsellor holds consultation and opens an application → Customer uploads documents; documentation team reviews; application submitted and tracked to approval → Customer books flight/hotel with markup pricing and pays online','["Home / Visa finder: Hero ''Your Journey Abroad Starts Here'', destination carousel, popular visas, offers,…", "Eligibility check: 7-step assessment (destination, visa type, age, education, work experience, English test,…", "Flights / Hotels: Search results with fares, filters, hotel detail, booking and checkout", "Customer dashboard: Overview, My Applications (status timeline), Documents, Consultations, Flight & Hotel…", "Admin: Leads: Leads with code, destination, visa type, eligibility status/score, priority, assigned…", "Admin: Applications / Document review: Applications with stage timeline; document queue"]'::jsonb,'["Next.js 16 App Router", "Supabase", "Postgres with RLS", "Auth", "Storage"]'::jsonb,'none',190) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('dinadena-labour','On-demand labour booking marketplace','DiNaDeNa','Labour marketplace · Jaipur','Mobile apps','Home services','the client connects households and shops with daily-wage workers from the local ''chowk'' (labourers, movers, masons, painters, plumbers, electricians, cleaners) for quick jobs or full-day hire. Customers post a job or book a specific worker, track them live, verify start/end with OTPs and pay by UPI; admins verify workers and set rates.','Main workflow: Customer logs in with OTP and posts a quick job (e.g. 2 loaders for 3 hours) or books a specific worker → Nearby verified workers get the request and accept within 10 minutes → Worker taps ''I''m on the way''; customer tracks live and shares Start OTP to check in → Worker requests extra time if needed; customer shares End OTP at finish → Customer pays on UPI screen and both leave reviews; admin sees it in Payments/Reports','["Welcome / Login: Language choice (English/Hindi), phone OTP login, onboarding as customer or worker", "Customer Home: Trade categories with icons and rates, nearby workers, active job card", "Post a job: Category, title, description, address on map, start time, duration, workers needed, price…", "Find workers / Worker profile: Workers filtered by trade, distance, rating and rate; profile with experience, area,…", "Job tracking: Status timeline, live worker location map, Start OTP / End OTP, extra-time requests, bill…", "Worker Home / Jobs: Online toggle, incoming requests with 10-min timer, nearby open jobs"]'::jsonb,'["Next.js", "client-rendered", "Supabase", "Postgres RLS", "SECURITY DEFINER RPCs", "Realtime"]'::jsonb,'none',200) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('kindbridge','Skill-exchange community app','KindBridge','Community platform','SaaS','Community','Neighbours earn ''help coins'' by helping one member and spend them to get help from another, with private usernames and opt-in sharing of real contact details. Organizers approve members, moderators handle disputes and reports, and an admin console manages communities, coins and audit logs.','Main workflow: Sign up with email OTP, pick an avatar username, join a community and get approved with starter coins → Choose skills you offer and need → Post or browse listings and propose an exchange with a coin amount → Helper accepts (coins reserved), delivers, requester confirms (coins settle) → Leave reviews; disputes go to moderators','["Home: Coin balance hero, suggested listings for your skills, active requests, updates", "Explore: Listings (offers and needs) by skill category with coins, duration, online/in-person", "Requests: Exchanges by status: Proposed, Booked, In progress, Awaiting confirmation, Completed", "Coins: Balance (available/reserved), ledger of earned and spent coins", "Profile: Username, avatar, bio, skills offered/needed, reviews, privacy and settings", "Create listing: Form: offer or need, category, title, description, duration, coins (max 60), format,…"]'::jsonb,'["Next.js 15 App Router", "server actions", "Prisma 6", "Supabase Postgres", "Zod", "Resend email OTP"]'::jsonb,'none',210) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('whatsmore','Messaging super app','WHATSMORE','Messaging start-up','SaaS','Communication','A WhatsApp-style messenger branded ''the client — More Than Chat'' that adds AI translation and summaries, payments, a marketplace, business catalogues, cloud files and community features in one app. Real accounts, chats, stories and WebRTC calls run on Supabase, with an admin panel for reports, verification badges and announcements.','Main workflow: Sign up with phone/email, OTP, choose unique @username → Find a contact by @username and start a chat → Chat with translation, AI summary and smart replies; share files and voice notes → Order from a business catalogue and pay with the client Pay → Admin reviews reports and grants verification badges','["Home: Greeting, quick actions, SOS, smart cards (unread messages, pending signature, scam…", "Chats: Chat list with unread badges, conversation view with replies, reactions, voice notes,…", "Status: Stories from contacts including a business offer, voice status", "Calls: Call history, call links, scheduled meetings", "Communities: Groups and announcement channels, polls, split bills", "Files: Cloud files auto-sorted into Photos, Documents, Receipts, Invoices; natural-language…"]'::jsonb,'["Next.js 16", "Supabase", "auth", "Postgres", "realtime", "RLS"]'::jsonb,'none',220) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('nearlane','Local discovery app','Nearlane','Local discovery start-up','Mobile apps','Local services','the client helps people find nearby shops, independent workers (locksmiths, cobblers, tailors), everyday services and underrated places, recommended by locals. Residents post photos of hidden gems, add listings, ask local questions and recommend providers; providers can claim listings and admins moderate.','Main workflow: Visitor picks a city/area and browses the Discover feed or searches Local → Opens a listing and taps Call/WhatsApp/Directions (contact intent tracked) → Resident signs in with Google, posts a hidden-gem photo or adds a missing listing → Provider claims their listing; moderator approves → Owner requests a labelled local promotion','["Discover: City photo feed of underrated places with captions, best time, likes/saves/comments; ''New…", "Local: Area picker, universal search, Services/Shops/Explore shortcuts, listing cards, sponsored…", "Listing detail: Title, kind (shop/stall/worker/home business/mobile service/place), hours, price range,…", "Post: Create a place post with 1-4 photos, place name, caption, best time, category", "Ask Locals: Local questions and answers by neighbourhood", "Saved: Saved listings and ''want to go'' places"]'::jsonb,'["Vite PWA", "Supabase", "Postgres", "PostGIS", "pg_trgm", "Google OAuth"]'::jsonb,'none',230) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('finscanix','AI invoice price-check SaaS','FinScanix','Procurement audit start-up','AI applications','Finance','Users upload vendor invoices and quotations; the client extracts the line items with AI OCR, matches each against CPWD/State PWD Schedule of Rates (adjusted by city index) and live market prices, and flags each line as over-priced, under-priced or at par. It produces an evidence-backed variance report so estimators and auditors can see where they are being overcharged.','Main workflow: Estimator uploads a vendor invoice or quotation and picks the project city → System checks image quality and extracts line items → Each item is matched to SoR (city-adjusted) and market prices → Report flags Over/Under/Par per item with evidence; user corrects low-confidence lines → Auditor exports the variance report and negotiates with vendor','["Dashboard: Totals (documents analysed, potential overcharge Rs, items flagged), variance charts,…", "Upload: Drop zone for PDF/images, quality checks (resolution, legibility), project and city…", "Documents: List of invoices/quotations with vendor, project, city, status, total, variance", "Invoice report: Line items with quantity, unit, vendor rate, SoR adjusted rate, market range, variance…", "Reports: Report builder across documents/vendors/date range", "Rate library: Schedule of Rates entries (code, description, unit, base rate, source) and city index…"]'::jsonb,'["Next.js 15 App Router", "Prisma", "Supabase Postgres", "Supabase Storage", "Gemini vision extraction", "Railway"]'::jsonb,'none',240) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_status","sort_order") VALUES ('hotel-concierge-ai','AI hotel concierge + bookings',NULL,'In-house product','AI applications','Hospitality','An AI system for hotels that answers guest enquiries on WhatsApp and the hotel website, checks real room availability, quotes prices, creates bookings and follows up with leads automatically, escalating to staff when unsure. Hotel managers see leads, conversations, bookings and a daily performance report in a dashboard and link their WhatsApp number by scanning a QR code.','Main workflow: Guest messages the hotel''s WhatsApp asking for a sea-view room → Orchestrator classifies intent; booking agent checks live inventory and quotes the total → Guest confirms; booking created atomically and lead marked BOOKED → Unconverted leads get automated follow-ups → Manager receives a daily report by email and WhatsApp','["Hotel website: Hotel hero, room types with photos and rates, availability search, offers, AI concierge…", "AI chat: Conversation where the AI answers policy questions from the knowledge base, quotes room…", "Dashboard - Overview: KPIs (enquiries, leads, bookings, revenue, conversion), exceptions needing human handoff", "Dashboard - Leads: Lead list with score, status, dates, room interest, next follow-up", "Dashboard - Conversations: WhatsApp/website threads with message status and which agent replied", "Dashboard - Bookings: Bookings with dates, room, guests, amount, payment status"]'::jsonb,'["Next.js web", "Claude-based agents", "orchestrator", "specialists", "Baileys WhatsApp service", "Supabase Postgres with RLS"]'::jsonb,'none',250) ON CONFLICT ("slug") DO NOTHING;
